<script setup>
import {Head,Link,router,usePage,useForm} from '@inertiajs/vue3';import {ref} from 'vue';import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';import ManagementPager from '../../Components/ManagementPager.vue';import {useI18n} from '../../lib/i18n.js';
const {t}=useI18n();
const props=defineProps({users:Object,filters:Object}),query=ref(props.filters?.q??''),page=usePage(),form=useForm({suspended:false});
function change(user){const suspended=!user.suspended_at;if(!confirm(t(suspended?'Suspend {name}? They will lose signed-in access until reactivated.':'Reactivate {name}? They will be able to sign in again.',{name:user.name})))return;form.suspended=suspended;form.patch(`/admin/users/${user.id}`,{preserveScroll:true});}
</script><template><Head :title="t('Account administration')"/><AppLayout :title="t('Account administration')"><template #actions><Link href="/admin/collections" class="button secondary">{{t('Collection administration')}}</Link></template><Errors :errors="form.errors"/><form class="admin-search panel" @submit.prevent="router.get('/admin/users',{q:query},{preserveState:true,replace:true})"><label>{{t('Search accounts')}}<input v-model="query" type="search" maxlength="100"/></label><button class="button">{{t('Search')}}</button></form><section class="panel"><p v-if="!users.data.length">{{t('No accounts match your search.')}}</p><article v-for="user in users.data" :key="user.id" class="admin-row"><div><strong>{{user.name}}</strong><p>{{user.email}}</p><span class="pill">{{t(user.is_admin?'Administrator':user.suspended_at?'Suspended':'Active')}}</span></div><button v-if="!user.is_admin&&user.id!==page.props.auth?.user?.id" class="button secondary" :disabled="form.processing" @click="change(user)">{{t(user.suspended_at?'Reactivate account':'Suspend account')}}</button></article><ManagementPager :page="users"/></section></AppLayout></template><style scoped>.admin-search{display:flex;align-items:flex-end;gap:12px;margin-bottom:20px}.admin-search label{flex:1;margin:0}.admin-row{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:18px 0;border-bottom:1px solid #ddd}.admin-row p{overflow-wrap:anywhere}@media(max-width:600px){.admin-row,.admin-search{flex-direction:column;align-items:stretch}}</style>